301	    pub fn select_agent(&mut self, agent_id: &AgentId) -> Result<(), String> {
302	        if self.agents.iter().any(|agent| &agent.id == agent_id) {
303	            self.selected_agent = Some(agent_id.clone());
304	            self.windows[self.active_window] = UiWindow::chat(agent_id.clone());
305	            self.control_selected = self
306	                .visible_agent_indices()
307	                .iter()
308	                .position(|index| self.agents[*index].id == *agent_id)
309	                .map(|position| position + 1)
310	                .unwrap_or(self.control_selected);
311	            self.reset_right_scroll();
312	            Ok(())
313	        } else {
314	            Err(format!("unknown agent `{agent_id}`"))
