437	    pub fn render_left_pane(&self) -> String {
438	        let mut rendered = String::new();
439	        if self.control_selected == 0 {
440	            rendered.push_str("> work-leaf  command\n");
441	        } else {
442	            rendered.push_str("  work-leaf  command\n");
443	        }
444	        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
445	            let agent = &self.agents[*agent_index];
446	            let mut row = String::new();
447	            row.push(if self.control_selected == visible_position + 1 {
448	                '>'
449	            } else {
450	                ' '
451	            });
452	            let (primary, secondary) = agent_list_labels(agent);
453	            row.push_str(primary);
454	            row.push(' ');
455	            row.push_str(secondary);
456	            row.push_str("  working: ");
457	            row.push_str(&agent.feature);
458	            if agent.ready {
459	                row.push_str("  READY");
460	                rendered.push_str("\u{1b}[7m");
461	                rendered.push_str(&row);
462	                rendered.push_str("\u{1b}[0m");
463	            } else {
464	                rendered.push_str(&row);
465	            }
466	            rendered.push('\n');
467	            if !agent.modified_files.is_empty() {
468	                rendered.push_str("    ");
469	                rendered.push_str("files: ");
470	                rendered.push_str(
471	                    &agent
472	                        .modified_files
473	                        .iter()
474	                        .map(|path| path.display().to_string())
475	                        .collect::<Vec<_>>()
476	                        .join(", "),
477	                );
478	                rendered.push('\n');
479	            }
480	            self.render_agent_links("conflicts", &agent.conflicting_agents, &mut rendered);
481	            self.render_agent_links("depends-on", &agent.depends_on, &mut rendered);
482	            self.render_agent_links("depended-on-by", &agent.depended_on_by, &mut rendered);
483	        }
484	        rendered
485	    }
