547	    fn render_tui_buffer(&self, right_content: &str, prompt: &str, prompt_cursor: usize) -> Buffer {
548	        let backend = TestBackend::new(self.width, self.height);
549	        let mut terminal = Terminal::new(backend).expect("test backend is valid");
550	        terminal
551	            .draw(|frame| {
552	                let area = frame.size();
553	                let body_height = area.height.saturating_sub(1);
554	                let body = Rect::new(area.x, area.y, area.width, body_height);
555	                let bottom = Rect::new(area.x, body_height, area.width, 1);
556	                let layout = self.layout();
557	                let panes = if layout.left_width > 0 {
558	                    Layout::default()
559	                        .direction(Direction::Horizontal)
560	                        .constraints([
561	                            Constraint::Length(layout.left_width),
562	                            Constraint::Length(layout.right_width),
563	                        ])
564	                        .split(body)
565	                } else {
566	                    vec![body]
567	                };
568	
569	                if layout.left_width > 0 {
570	                    frame.render_widget(self.left_widget(), panes[0]);
571	                    frame.render_widget(self.right_widget(right_content), panes[1]);
572	                } else {
573	                    frame.render_widget(self.right_widget(right_content), panes[0]);
574	                }
575	                frame.render_widget(
576	                    Paragraph::new(self.bottom_line(prompt, prompt_cursor)),
577	                    bottom,
578	                );
579	            })
580	            .expect("test backend draw succeeds");
581	        terminal.backend().buffer().clone()
582	    }
