1236	fn visible_content(content: &str, width: u16, height: u16, scroll_rows: usize) -> String {
1237	    let height = usize::from(height);
1238	    let Some((history, prompt)) = split_chat_prompt(content) else {
1239	        return tail_visible_content(content, width, height, scroll_rows);
1240	    };
1241	
1242	    let prompt_rows = visual_row_count(prompt, width);
1243	    let history_height = height.saturating_sub(prompt_rows).max(1);
1244	    let visible_history = tail_visible_content(history, width, history_height, scroll_rows);
1245	    if visible_history.is_empty() {
1246	        prompt.to_string()
1247	    } else {
1248	        format!("{visible_history}\n{prompt}")
