491	        } else if sequence.bytes.len() > MAX_ESCAPE_SEQUENCE {
492	            let sequence = self
493	                .escape_sequence
494	                .take()
495	                .expect("escape sequence is present");
496	            self.dispatch_pending_escape_if_needed(&sequence);
497	        }
498	
499	        true
