523	fn parse_key_sequence(bytes: &[u8]) -> Option<(UiKey, usize)> {
524	    match bytes {
525	        [27, b'[', b'A', ..] => Some((UiKey::Up, 3)),
526	        [27, b'[', b'B', ..] => Some((UiKey::Down, 3)),
527	        [27, b'[', b'C', ..] => Some((UiKey::Right, 3)),
528	        [27, b'[', b'D', ..] => Some((UiKey::Left, 3)),
529	        _ => parse_sgr_mouse_sequence(bytes),
