533	fn parse_sgr_mouse_sequence(bytes: &[u8]) -> Option<(UiKey, usize)> {
534	    if !bytes.starts_with(b"\x1b[<") {
535	        return None;
536	    }
537	
538	    let final_index = bytes.iter().position(|byte| matches!(byte, b'M' | b'm'))?;
539	    let final_byte = bytes[final_index];
540	    let body = std::str::from_utf8(&bytes[3..final_index]).ok()?;
541	    let mut parts = body.split(';');
542	    let button = parts.next()?.parse::<u16>().ok()?;
543	    let column = parts.next()?.parse::<u16>().ok()?;
544	    let row = parts.next()?.parse::<u16>().ok()?;
545	    if parts.next().is_some() {
546	        return None;
547	    }
548	
549	    let button_kind = button & !0b0001_1100_u16;
550	    let key = match (button_kind, final_byte) {
551	        (64, b'M') => UiKey::MouseScrollUp { column, row },
552	        (65, b'M') => UiKey::MouseScrollDown { column, row },
553	        (_, b'M' | b'm') if button_kind < 64 && button & 0b11 == 0 => {
554	            UiKey::MouseClick { column, row }
555	        }
556	        _ => return None,
557	    };
558	    Some((key, final_index + 1))
559	}
